/* ============================================================
 * INPUTS (DP=$1D00, i.e. $7E:1DXX):
 *   A on entry = 16-bit "cell source" position word (low byte = X pixel pos,
 *                high byte = Y pixel pos of the point probed).
 *   $1D1E/$1D1F (16-bit) = CELL MASK; (pos_word AND mask) = linear byte index
 *                into the 0x40-stride property planes (= tile_y*0x40 + tile_x,
 *                with the per-axis bounds folded in).
 * OUTPUTS:
 *   carry: SET = off-map / SOLID; CLEAR = in-bounds (bytes loaded).
 *   $1D58 = prop byte0 (shape = (byte0&0xFC)>>2; bit0/bit1 = actor-block flags)
 *   $1D5A = prop byte1 (byte1&0x10 = DOOR; conveyor source at apply 9C5C)
 *   $1D5C = prop byte2 (byte2&3 = z-plane; &4 IGNORE_Z; &8 INVERTED;
 *           &0x20 Z_NEUTRAL; &0x40 SPRITE_FRONT_BOTTOM)
 *   X (16-bit) = the computed cell index (left in X on return)
 * PLANES (absolute long WRAM despite $7E; X is 16-bit absolute index):
 *   $7E70C0[i] off-map SENTINEL (bit7 CLEAR => off-map); $7E30C0 byte0;
 *   $7E7000 byte1; $7E7040 byte2.
 * ============================================================ */

/* ---- C0/9AA1 : fetch WITH off-map sentinel early-out ---- */
bool prop_fetch_checked(uint16_t pos_word /* the 16-bit A on entry */)
{
    /* 9AA1 REP #$10 ; 9AA3 REP #$20  -> X & A 16-bit */
    uint16_t idx = pos_word & DP16(0x1E);      /* 9AA5 AND $1E (vs $1D1E/$1D1F) */
    /* 9AA7 SEP #$20  -> A 8-bit (X stays 16-bit) */
    uint16_t X = idx;                          /* 9AA9 TAX */

    uint8_t sentinel = WRAM8(0x7E70C0 + X);    /* 9AAA LDA $7E70C0,X (8-bit) */
    if (sentinel & 0x80) {                      /* 9AAE BMI $9AB2 : branch taken iff bit7 SET */
        return prop_fetch_tail(X);             /* -> tail, returns false (carry clear) */
    }
    /* 9AB0 SEC ; 9AB1 RTS */
    return true;                               /* CARRY SET = off-map / SOLID */
}

/* ---- C0/9AB2 : common tail (load 3 prop bytes, carry clear) ---- */
bool prop_fetch_tail(uint16_t X /* 16-bit cell index */)
{
    DP8(0x58) = WRAM8(0x7E30C0 + X);           /* 9AB2/9AB6  byte0 */
    DP8(0x5A) = WRAM8(0x7E7000 + X);           /* 9AB8/9ABC  byte1 */
    DP8(0x5C) = WRAM8(0x7E7040 + X);           /* 9ABE/9AC2  byte2 */
    /* 9AC4 SEP #$10 (X->8-bit) ; 9AC6 CLC */
    return false;                              /* 9AC7 RTS, CARRY CLEAR */
}

/* ---- C0/9AC8 : fetch WITHOUT sentinel check (always loads) ---- */
bool prop_fetch_unchecked(uint16_t pos_word)
{
    /* 9AC8 REP #$10 ; 9ACA REP #$20 */
    uint16_t idx = pos_word & DP16(0x1E);      /* 9ACC AND $1E */
    /* 9ACE SEP #$20 */
    uint16_t X = idx;                          /* 9AD0 TAX */
    return prop_fetch_tail(X);                 /* 9AD1 BRA $9AB2 */
}

/* ---- C0/9AD3 : shape-decode prologue (NOT a fetch) ---- */
void collision_result_init_and_shape_head(void)
{
    DP8(0x5E) = 0;   /* 9AD3 one-way scratch */
    DP8(0x60) = 0;   /* 9AD5 shape-index scratch */
    DP8(0x6A) = 0;   /* 9AD7 z-plane out */
    DP8(0x6C) = 0;   /* 9AD9 IGNORE_Z out */
    DP8(0x6E) = 0;   /* 9ADB sprite-prio out */
    DP8(0x56) = DP8(0x68) >> 2;   /* 9ADD/9ADF/9AE0/9AE1: $1D56 = ($1D68>>2) sub-tile Y */
    /* 9AE3 LDA $58 ... falls into shape decode (shape=(byte0&0xFC)>>2) */
}
